package org.mndt.core

import com.fasterxml.jackson.databind.ObjectMapper
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.time.Instant

/**
 * hazard §8 / importer §3: whether a re-post is an authorized importer's is decided from the post's own chain and the
 * local trust config, so the same post gives the same answer whether it came from the relay or over the mesh.
 * hazard-import.json is generated by the BSAF publisher code with throwaway keys (iOS reads the same file).
 */
class HazardImportTest {
    private val fixture = ObjectMapper().readTree(javaClass.getResource("/hazard-import.json")!!.readText())
    private val config = PublicIngress.config(fixture["config"].toString())
    private fun event(name: String) = NostrEvent.fromJson(fixture[name].toString())
    private fun view(e: NostrEvent, selected: Set<PublicIngress.Selection> = config.selected): PublicIngress.ChainView {
        val now = Instant.ofEpochSecond(e.createdAt + 60)
        return PublicIngress.chainView(e, config.roots, PublicIngress.RevocationStore(), now, now, selected)!!
    }

    @Test fun authorizedImporterIsRecognizedFromThePostAlone() {
        val trusted = event("trusted")
        val v = view(trusted)
        assertTrue(v.confirmedNow && v.importAuthorized)
        // Same verdict as the relay ingress check, which additionally requires a live delivery deadline.
        assertEquals(true, PublicIngress.verify(trusted, config, PublicIngress.RevocationStore(), Instant.ofEpochSecond(trusted.createdAt + 60)).receipt != null)
    }

    @Test fun trustChoicesSwitchAndAddRoots() {
        val testRoot = "fcf986bb79a0527e4b6af50ae8bc32dde9ae81c189b06614a6a1fe3c44bca2ff"
        val test = PublicIngress.config("""{"roots":[{"pubkey":"$testRoot","name":"t","roles":["attest","import"],"maxDepth":2,"enabled":true}],"selected":[]}""")
        val builtinKey = config.roots.single().pubkeyHex
        val userKey = "3b92115866d54bb1799529ac39312bcd60bbfc1f5235b5785f4f7db748c62510"
        val choices = PublicIngress.TrustChoices(disabled = setOf(builtinKey), added = listOf(userKey to "追加", "not-a-key" to "bad"))
        val (effective, entries) = PublicIngress.effective(config, test, PublicIngress.TrustChoices.parse(choices.toJson()))
        assertEquals(listOf(PublicIngress.RootOrigin.BUILTIN, PublicIngress.RootOrigin.TEST, PublicIngress.RootOrigin.USER), entries.map { it.origin })
        assertEquals(listOf(false, true, true), effective.roots.map { it.enabled })
        assertEquals(config.selected, effective.selected)
        // A switched-off root no longer authorizes; switching it back restores the verdict.
        assertFalse(PublicIngress.chainView(event("trusted"), effective.roots, PublicIngress.RevocationStore(),
            Instant.ofEpochSecond(event("trusted").createdAt + 60), Instant.ofEpochSecond(event("trusted").createdAt + 60), effective.selected)!!.confirmedNow)
        assertEquals(null, PublicIngress.rootKey("xyz"))
        assertEquals(PublicIngress.TrustChoices(), PublicIngress.TrustChoices.parse("{broken"))
    }

    @Test fun untrustedOrUnselectedIsNotAuthorized() {
        assertFalse(view(event("untrusted")).importAuthorized)
        assertFalse(view(event("trusted"), selected = emptySet()).importAuthorized)
        // No usable clock: never confirmed.
        val trusted = event("trusted")
        assertFalse(PublicIngress.chainView(trusted, config.roots, PublicIngress.RevocationStore(), null, Instant.ofEpochSecond(trusted.createdAt), config.selected)!!.confirmedNow)
    }
}
